var lineitem_facts = relationOfFacts(lpFacts['lineitem/13'] || []);

var lineitem = lineitem_facts;

var instances_late_lineitem = [].concat(
  // late_lineitem(O) :- lineitem(O,_,_,_,_,_,_,_,_,Commit,Receipt,_,_), Commit < Receipt.
  (function() {
    return _.flatten(map(function(e1) {
      var O = e1.t[0];
      var Commit = e1.t[9];
      var Receipt = e1.t[10];
      if (Commit < Receipt) {
        return [['late_lineitem', [O], e1.v]];
      } else {
        return [];
      }
    }, _.values(lineitem)));
  })()
);
var late_lineitem = relation({}, instances_late_lineitem);

var orders = orders_facts;

var instances_q4_priority = [].concat(
  // q4_priority(Pri) :- orders(O,_,_,Date,Pri), Date >= 19930701, Date < 19931001, late_lineitem(O).
  (function() {
    return _.flatten(map(function(e1) {
      var O = e1.t[0];
      var Date = e1.t[3];
      var Pri = e1.t[4];
      if (Date >= 19930701) {
        if (Date < 19931001) {
          return _.flatten(map(function(e2) {
            return [['q4_priority', [Pri], and([e1.v, e2.v])]];
          }, probe(late_lineitem, [O])));
