var instances_q4 = [].concat(
  // q4 :- q4_priority(_).
  (function() {
    return _.flatten(map(function(e1) {
      return [['q4', [], e1.v]];
    }, _.values(q4_priority)));
  })()
);
var q4 = relation({}, instances_q4);

// component 0 bool
var model = function() {
  return [holds(q4, [])()];
};
Infer({method: 'enumerate'}, model);

